custom_options:
{
  "x_field": "event",
  "chart_type": "Bar",
  "y_axis_fields": [
    {
      "y_field": "tickets_sold",
      "name": "Tickets Sold",
      "color": "#3B82F6",
      "bar_width": 18,
      "show_values": true,
      "value_color": "#1E293B",
      "value_font_size": 12
    },
    {
      "y_field": "total_amount",
      "name": "Total Revenue",
      "color": "#F97316",
      "bar_width": 18,
      "show_values": true,
      "value_color": "#1E293B",
      "value_font_size": 12
    }
  ],
  "y_fields": ["tickets_sold", "total_amount"],
  "colors": ["#3B82F6", "#F97316"],
  "axis_options": {
    "x_axis_label": "Event",
    "y_axis_label": "Count / Revenue",
    "x_axis_rotate": 45,
    "shorten_numbers": true
  },
  "tooltip_options": {
    "background_color": "#1E293B",
    "text_color": "#F8FAFC",
    "border_radius": 6,
    "shadow": true,
    "format_tooltip_y": "function(value, field) { return field === 'total_amount' ? '₹' + value : value + ' tickets'; }"
  },
  "legend": {
    "position": "top",
    "align": "center",
    "label_color": "#475569",
    "font_size": 13
  },
  "grid": {
    "visible": true,
    "color": "#E2E8F0"
  },
  "max_rows": 20
}
